let seattleCatalogPromise;
function seattleCatalogPage(){return journeyPage(2,'Read the source. Keep your options open.',`<p class="journey-lede">Seattle Colleges’ 2025–27 catalog, available here as searchable campus sections and all 340 source pages.</p><p>The 286 indexed headings include degree programs, transfer focus areas and noncredit training. They are not 286 separate credentials, and extracted course mentions are not automatic degree requirements.</p><div class="form-grid"><label>Campus<select id="seattle-source-campus"><option value="">All campuses</option><option>North Seattle College</option><option>Seattle Central College</option><option>South Seattle College</option></select></label><label>Program heading<input id="seattle-source-query" type="search" maxlength="150" placeholder="Engineering, science, arts…"></label><label>Read an exact PDF page<input id="seattle-source-page" type="number" min="1" max="340" placeholder="1–340"></label></div><button class="btn" id="open-seattle-source-page">Open source page →</button><div id="seattle-source-results" aria-live="polite"><p role="status">Opening catalog sections…</p></div><section id="seattle-source-reader" class="degree-optimizer" hidden></section>`,'degrees')}
async function bindSeattleCatalog(){const input=document.querySelector('#seattle-source-query');if(!input)return;try{if(!seattleCatalogPromise)seattleCatalogPromise=Promise.all(['seattle-catalog-sections.json','seattle-catalog-pages.json'].map(path=>fetch(path).then(r=>{if(!r.ok)throw Error('Seattle catalog snapshot unavailable.');return r.json()}))).catch(e=>{seattleCatalogPromise=null;throw e});const[sections,pages]=await seattleCatalogPromise;if(!input.isConnected)return;let offset=0;const open=record=>{const target=document.querySelector('#seattle-source-reader');target.hidden=false;target.innerHTML=`<span class="eyebrow">${esc(record.campus||'Seattle Colleges')} · ${esc(record.catalogYear)}</span><h3>${esc(record.title||'PDF page '+record.pdfPage)}</h3><div class="uw-source-text" tabindex="0">${esc(record.text)}</div><a class="journey-secondary" href="${esc(record.sourceUrl)}" target="_blank" rel="noopener">Original official PDF page ↗</a><p>${esc(record.note||'Extracted source page, not an automatically interpreted degree audit.')}</p>`;target.scrollIntoView({block:'start',behavior:state.reduceMotion?'auto':'smooth'})};const draw=()=>{const campus=document.querySelector('#seattle-source-campus').value,rows=sections.filter(r=>(!campus||r.campus===campus)&&r.title.toLowerCase().includes(input.value.toLowerCase())),target=document.querySelector('#seattle-source-results');target.innerHTML=`<p>${rows.length} indexed sections · checked November 9, 2026</p>${rows.slice(offset,offset+15).map(r=>`<article class="degree-goal"><span class="eyebrow">${esc(r.campus)}</span><h3>${esc(r.title)}</h3><button class="btn" data-seattle-section="${esc(r.id)}">Read the source section →</button></article>`).join('')}<div class="journey-actions"><button class="btn" data-seattle-prev ${!offset?'disabled':''}>← Previous</button><button class="btn" data-seattle-next ${offset+15>=rows.length?'disabled':''}>Next →</button></div>`;target.querySelectorAll('[data-seattle-section]').forEach(b=>b.onclick=()=>open(sections.find(r=>r.id===b.dataset.seattleSection)));target.querySelector('[data-seattle-prev]').onclick=()=>{offset-=15;draw()};target.querySelector('[data-seattle-next]').onclick=()=>{offset+=15;draw()}};input.oninput=()=>{offset=0;draw()};document.querySelector('#seattle-source-campus').onchange=()=>{offset=0;draw()};document.querySelector('#open-seattle-source-page').onclick=()=>{const n=+document.querySelector('#seattle-source-page').value,record=pages.find(r=>r.pdfPage===n);if(!record)return toast('Choose a source page from 1 to 340.');open(record)};draw()}catch(e){if(input.isConnected)document.querySelector('#seattle-source-results').textContent=e.message}}
function installSeattleCatalog(){const oldBind=bind;bind=()=>{oldBind();bindSeattleCatalog()};const oldSourceLibrary=sourceLibrary;sourceLibrary=()=>oldSourceLibrary()+`<div class="journey-actions"><a class="btn" href="#bellevue-catalog">Bellevue programs & maps →</a><a class="btn" href="#seattle-catalog">Read Seattle Colleges’ full catalog →</a></div>`}
